// Method: Curve3D::get_closest_point
static JSValue js_Curve3D_get_closest_point(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "Curve3D.get_closest_point: missing handle argument");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "Curve3D.get_closest_point: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }


    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "Curve3D.get_closest_point: invalid or freed object");
    }

    Curve3D* typed_obj = Object::cast_to<Curve3D>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "Curve3D.get_closest_point: object is not a Curve3D");
    }

    // Argument count check (excluding handle) - only required args
    if (argc < 2) {
        return JS_ThrowTypeError(ctx, "Curve3D.get_closest_point: expected at least 1 arguments, got %d", argc - 1);
    }

    // Convert arguments
    double tmp_x_to_point, tmp_y_to_point, tmp_z_to_point;
    JSValue jx_to_point = JS_GetPropertyStr(ctx, argv[1], "x");
    JSValue jy_to_point = JS_GetPropertyStr(ctx, argv[1], "y");
    JSValue jz_to_point = JS_GetPropertyStr(ctx, argv[1], "z");
    JS_ToFloat64(ctx, &tmp_x_to_point, jx_to_point);
    JS_ToFloat64(ctx, &tmp_y_to_point, jy_to_point);
    JS_ToFloat64(ctx, &tmp_z_to_point, jz_to_point);
    JS_FreeValue(ctx, jx_to_point);
    JS_FreeValue(ctx, jy_to_point);
    JS_FreeValue(ctx, jz_to_point);
    Vector3 arg_to_point(tmp_x_to_point, tmp_y_to_point, tmp_z_to_point);

    Vector3 result = typed_obj->get_closest_point(arg_to_point);
    JSValue ret_obj = JS_NewObject(ctx);
    JS_SetPropertyStr(ctx, ret_obj, "x", JS_NewFloat64(ctx, result.x));
    JS_SetPropertyStr(ctx, ret_obj, "y", JS_NewFloat64(ctx, result.y));
    JS_SetPropertyStr(ctx, ret_obj, "z", JS_NewFloat64(ctx, result.z));
    return ret_obj;
}

